CREATE TABLE public.game_format_prompts (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, format text NOT NULL CHECK (format IN ('card','wheel','vote')), title text NOT NULL, prompt text NOT NULL, depth text NOT NULL DEFAULT 'light' CHECK (depth IN ('light','getting to know','deeper')), icon text NOT NULL DEFAULT '✦', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.game_format_prompts TO authenticated;
GRANT ALL ON public.game_format_prompts TO service_role;
ALTER TABLE public.game_format_prompts ENABLE ROW LEVEL SECURITY;
CREATE POLICY game_format_prompts_read ON public.game_format_prompts FOR SELECT TO authenticated USING (true);
CREATE FUNCTION public.game_format_prompts_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER game_format_prompts_updated BEFORE UPDATE ON public.game_format_prompts FOR EACH ROW EXECUTE FUNCTION public.game_format_prompts_updated_at();
INSERT INTO public.game_format_prompts(format,title,prompt,depth,icon)
SELECT 'card', CASE WHEN n <= 12 THEN 'Getting to know you' WHEN n <= 24 THEN 'Would you rather' WHEN n <= 36 THEN 'Two truths & a lie' WHEN n <= 48 THEN 'Hot seat' ELSE 'Finish the sentence' END, p, CASE WHEN n <= 20 THEN 'light' WHEN n <= 40 THEN 'getting to know' ELSE 'deeper' END, CASE WHEN n <= 12 THEN '💬' WHEN n <= 24 THEN '↔️' WHEN n <= 36 THEN '🎭' WHEN n <= 48 THEN '⚡' ELSE '✨' END FROM unnest(ARRAY[
'What tiny thing made you laugh this week?','What is your most oddly specific talent?','What food feels like home?','What song reminds you of a good friend?','What would your perfect slow Sunday look like?','What is your favorite shared memory with this squad?','What is the funniest thing in your camera roll that you are happy to share?','What is your favorite way to spend a free afternoon?','What is a harmless habit your friends tease you about?','Which trip snack is always in your bag?','What is a place you would go back to tomorrow?','What is your go-to way to cheer someone up?',
'Would you rather take a train through the mountains or a boat along the coast?','Would you rather be the DJ or the photographer tonight?','Would you rather always find the best café or the best view?','Would you rather know every language or cook every cuisine?','Would you rather plan a surprise or be surprised?','Would you rather have a sunrise picnic or a midnight dessert?','Would you rather revisit a favorite place or discover a new one?','Would you rather travel with one small bag or bring every outfit?','Would you rather see the city by bike or on foot?','Would you rather host dinner or bring the best dessert?','Would you rather learn a dance or learn a recipe together?','Would you rather have a quiet cabin or a lively city weekend?',
'Tell two true stories and one made-up story about your childhood. Let us guess.','Tell two truths and a lie about your first job.','Tell two truths and a lie about places you have visited.','Tell two truths and a lie about foods you have tried.','Tell two truths and a lie about your hidden talents.','Tell two truths and a lie about your favorite music.','Tell two truths and a lie about a memorable school day.','Tell two truths and a lie about your best birthday.','Tell two truths and a lie about your travel habits.','Tell two truths and a lie about a funny family tradition.','Tell two truths and a lie about a skill you want to learn.','Tell two truths and a lie about an unexpected friendship.',
'Hot seat: in 30 seconds, name three things that always brighten your day.','Hot seat: what would your best friend say is your superpower?','Hot seat: name three places that feel like home.','Hot seat: what do you wish people asked you more often?','Hot seat: who knows your comfort-food order by heart?','Hot seat: what is something about you that old friends still get wrong?','Hot seat: name three little things you appreciate about this squad.','Hot seat: what is the best advice you actually followed?','Hot seat: what is one way you have surprised yourself lately?','Hot seat: what do you hope this squad remembers about this trip?','Hot seat: what is a story you never get tired of telling?','Hot seat: what is one thing a new friend should know about you?',
'Finish the sentence: A perfect day together starts with…','Finish the sentence: I feel most like myself when…','Finish the sentence: The best surprise I ever got was…','Finish the sentence: I knew we were friends when…','Finish the sentence: One thing I hope we do together is…','Finish the sentence: Something I used to be afraid to try is…','Finish the sentence: The person who taught me the most about friendship is…','Finish the sentence: If you have known me forever, you might still get this wrong…','Finish the sentence: A moment I wish I could replay is…','Finish the sentence: I feel welcome when someone…','Finish the sentence: My favorite thing about getting older is…','Finish the sentence: The next chapter I am excited for is…']::text[]) WITH ORDINALITY AS t(p,n);
INSERT INTO public.game_format_prompts(format,title,prompt,depth,icon) SELECT 'wheel', t, p, 'light', i FROM unnest(ARRAY['Draw it|Sketch a simple object in 20 seconds. The squad guesses out loud.|🎨','Sock check|What color are your socks? Everyone guesses before you show them.|🧦','Guess the song|Sing or say a line from a favorite song. The squad guesses out loud.|🎵','Act it out|Act out a vacation activity without words.|🎭','Emoji story|Tell a tiny story using only three emojis.|😀','Tongue twister|Try a silly tongue twister twice, as fast as you can.|👅','Last photo|Show the last photo you took that you are OK sharing.|📷','Three words|Describe your day in just three words.|💬','Quick doodle|Draw your dream breakfast in 20 seconds.|🎨','Movie mime|Act out a movie genre for the squad to guess.|🎬','Memory lane|Act out a shared squad memory without naming it.|🎭','Favorite sound|Hum a tune you love; let the squad guess.|🎵','Color hunt|Point to something near you in your favorite color.|🌈','Packing mime|Pretend to pack one item. Everyone guesses it.|🧳','Emoji destination|Describe a place with three emojis.|🌍','One-minute pitch|Pitch your dream snack in one breath.|🍿','Draw a creature|Sketch an imaginary animal in 20 seconds.|🎨','Day in gestures|Describe your day using only gestures.|👋','Snack debate|Defend your favorite snack in 20 seconds.|🍪','Accent-free song|Hum a favorite song; no lyrics on the screen.|🎶','Mystery object|Describe something near you without naming it.|🔎','Travel pose|Strike your best airport pose.|✈️','Draw a view|Draw your favorite view in 20 seconds.|🏞️','Emoji mood|Show today’s mood with three emojis.|😎','Vacation sound|Make a sound from a place you love.|🎤','Three-word story|Make up a story about this squad in three words.|📖','Funny face|Make a face that sums up this week.|😜','Dream souvenir|Draw a souvenir you wish existed.|🎨','Who am I?|Act out someone in the squad kindly; let them guess.|🎭','Compliment relay|Say one kind thing about the person to your left.|💛']) AS x(v) CROSS JOIN LATERAL (SELECT split_part(v,'|',1) t,split_part(v,'|',2) p,split_part(v,'|',3) i) q;
INSERT INTO public.game_format_prompts(format,title,prompt,depth,icon) SELECT 'vote', t, p, 'light', i FROM unnest(ARRAY['Best dressed|Who best fits tonight’s theme?|👗','Best singer|Who gave the most joyful performance?|🎤','Funniest answer|Who made you laugh hardest tonight?|😂','Best story|Whose story will you remember tomorrow?|📖','Most likely to explore|Who would spot the best detour?|🧭','Best impression|Who had the funniest impression?|🎭','Best drawing|Whose doodle deserves a museum wall?|🎨','Best host moment|Who made everyone feel most welcome?|💛','Best unexpected fact|Whose fact surprised you most?|✨','Best dance move|Who owned the dance floor tonight?|💃','Most likely to pack snacks|Who would remember snacks for everyone?|🍿','Best travel tip|Who shared the most useful travel tip?|✈️','Best comeback|Who had the cleverest reply?|⚡','Best squad spirit|Who brought the squad together tonight?|🌟','Most likely to find a café|Who would find the coziest corner?|☕','Best three-word story|Who told the best tiny story?|📚','Best game face|Who committed hardest to the bit?|🎲','Best kind moment|Who made someone smile tonight?|💚','Most likely to lead karaoke|Who would start the sing-along?|🎵','Best memory|Whose memory warmed your heart?|📸']) AS x(v) CROSS JOIN LATERAL (SELECT split_part(v,'|',1) t,split_part(v,'|',2) p,split_part(v,'|',3) i) q;